import bisect


def dp_opt_bit_hamiltonian(adj):
    """状态设计优化(Hamiltonian 判定, n<=20) 的位压缩版:
    常规 O(n^2 2^n) 用位集压缩为 O(n 2^n / w).
    这里用 Python int 作为位集: dp[mask] 的第 i 位 = 能否以 i 结尾访问 mask."""
    n = len(adj)
    dp = [0] * (1 << n)
    for s in range(n):
        dp[1 << s] |= 1 << s  # 可从任意点出发
    for mask in range(1 << n):
        ends = dp[mask]
        if not ends:
            continue
        # 遍历可作为末端的点 i (dp[mask] 的置位)
        m = ends
        while m:
            lb = m & -m
            i = lb.bit_length() - 1
            # 从 i 扩展到相邻且不在 mask 中的 j
            reach = adj[i] & ~mask
            r = reach
            while r:
                lj = r & -r
                dp[mask | lj] |= lj
                r ^= lj
            m ^= lb
    full = (1 << n) - 1
    return dp[full] != 0


def hamiltonian_brute(adj):
    """暴力回溯验证小数据。"""
    n = len(adj)

    def rec(v, visited, count):
        if count == n:
            return True
        for u in range(n):
            if (adj[v] >> u) & 1 and not (visited >> u) & 1:
                if rec(u, visited | (1 << u), count + 1):
                    return True
        return False

    for s in range(n):
        if rec(s, 1 << s, 1):
            return True
    return False


def random_graph(n, p):
    adj = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j and random.random() < p:
                adj[i] |= 1 << j
                adj[j] |= 1 << i
    return adj


if __name__ == "__main__":
    import random
    for _ in range(60):
        n = random.randint(2, 7)
        g = random_graph(n, 0.5)
        a = dp_opt_bit_hamiltonian(g)
        b = hamiltonian_brute(g)
        assert a == b, (g, a, b)
    # 路径图: 0-1-2-... 存在哈密顿路径
    n = 6
    adj = [0] * n
    for i in range(n - 1):
        adj[i] |= 1 << (i + 1)
        adj[i + 1] |= 1 << i
    assert dp_opt_bit_hamiltonian(adj) is True
    # 完全二分 K3,3 无边不成图? 构造孤立点: 无哈密顿
    adj = [0] * 5
    assert dp_opt_bit_hamiltonian(adj) is False
    print("dp_opt state-design (bit-hamiltonian) tests passed")
